uip is connections list --all-folders --output json 2>&1 | python3 -c "
import json, sys
d = json.load(sys.stdin)
conns = d.get('Data', [])
for c in conns:
    folder = c.get('Folder','')
    if 'spotify' in c.get('ConnectorKey','').lower() or 'spotify' in c.get('ConnectorName','').lower() or 'spotify' in c.get('Name','').lower():
        print(json.dumps(c, indent=2))
print('--- all connections in uipath-maestro-flow folder ---')
for c in conns:
    if c.get('Folder','') == 'uipath-maestro-flow':
        print(json.dumps({k: c.get(k) for k in ['Id','Name','ConnectorKey','ConnectorName','State','Folder','FolderKey']}, indent=2))
"

